syntax:
```cpp
constexpr int square(int x) { return x * x; }

int main() {
  constexpr int x = 5;
  constexpr int y = square(x); // Computation happens at compile time
  std::cout << y << std::endl; // No runtime calculation
  int z = square(10);  //May or may not be compile-time depending on compiler and optimization level.
  std::cout << z << std::endl; //Potentially still a runtime calculation
  return 0;
}
```
